function canVisitOutfitShop(){return !game&&(!live||live.phase==='lobby')||!!live&&live.phase==='lobby'&&!live.battleStarted&&!live.roundStarted}
function openWardrobe(){if(!canVisitOutfitShop()){toast('Open your wardrobe between rounds.');return}const inv=shopInventory(),eq=equippedCosmetic(),rows=[...COSTUME_ITEMS.map(i=>({...i,kind:'costume'})),...ACCESSORY_ITEMS.map(i=>({...i,kind:'accessory'}))].filter(i=>!i.cost||inv[i.kind+':'+i.id]);openModal(`${topModal('YOUR PERMANENT WARDROBE').replace('data-action="close"','data-wardrobe-close')}<h2 id="modal-title">Owned once. Yours to keep.</h2><p class="sub">${rows.length} wardrobe items · Equip any owned look for free. Outfits work in solo and live games and do not add combat power.</p><div class="modal-actions"><button class="secondary" data-shop-tab="costumes">Shop outfits</button><button class="secondary" data-shop-tab="accessories">Shop accessories</button></div><div class="shop-grid">${rows.map(item=>{const active=eq[item.kind==='costume'?'outfit':'accessory']===item.id,cosmetic={...eq,[item.kind==='costume'?'outfit':'accessory']:item.id};return `<article class="shop-item cosmetic-item ${active?'equipped':''}" style="--item-colour:${item.colour}"><button class="cosmetic-model" data-cosmetic-preview="${item.kind}:${item.id}" aria-label="Enlarge and animate ${item.name}">${heroSVG(profile.hero,'',undefined,undefined,undefined,cosmetic)}</button><small>${item.rarity} · PERMANENTLY OWNED</small><h3>${item.name}</h3><button class="${active?'secondary':'primary'}" data-wardrobe-equip="${item.kind}:${item.id}" ${active?'disabled':''}>${active?'Equipped ✓':'Equip · free'}</button></article>`}).join('')}</div><button class="primary" data-wardrobe-close>Back to ${live?'crew':'game'} →</button>`)}
const wardrobeShop=creditShop;creditShop=function(tab='armour'){if(tab==='wardrobe'){openWardrobe();return}if(live&&canVisitOutfitShop()&&!['costumes','accessories'].includes(tab))tab='costumes';wardrobeShop(tab);if(document.querySelector('.shop-tabs'))document.querySelector('.shop-tabs')?.insertAdjacentHTML('beforeend','<button data-shop-tab="wardrobe">My wardrobe</button>');if(live&&canVisitOutfitShop()){const close=document.querySelector('#modal-content [data-action="close"]');if(close){close.removeAttribute('data-action');close.setAttribute('data-wardrobe-close','')}}};
const wardrobeHome=home;home=function(){return wardrobeHome().replace('<button class="secondary" data-shop-tab="armour">◆ Credit shop</button>','<button class="secondary" data-shop-tab="armour">◆ Shop · Gear & outfits</button><button class="secondary" data-shop-tab="wardrobe">▣ My wardrobe</button>')};
const wardrobeLobby=drawLiveLobby;drawLiveLobby=function(){wardrobeLobby();if(live?.phase==='lobby'&&!document.querySelector('[data-crew-wardrobe]'))document.querySelector('.live-roster')?.insertAdjacentHTML('afterend','<button class="secondary" data-crew-wardrobe data-shop-tab="wardrobe">▣ Wardrobe & outfit shop</button>')};
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-wardrobe-close')){event.preventDefault();event.stopImmediatePropagation();closeModal();if(live?.phase==='lobby'){live.lastLobby='';drawLiveLobby()}}if(b.dataset.wardrobeEquip){event.preventDefault();event.stopImmediatePropagation();const[kind,id]=b.dataset.wardrobeEquip.split(':');const list=kind==='costume'?COSTUME_ITEMS:ACCESSORY_ITEMS,item=list.find(i=>i.id===id);if(!item||item.cost&&!shopInventory()[kind+':'+id]||!canVisitOutfitShop())return;profile.cosmetics??={outfit:'classic',accessory:'none'};profile.cosmetics[kind==='costume'?'outfit':'accessory']=id;avatarSprites.clear();operatorFrames.clear();save();GameAudio.effect('click');openWardrobe()}},true);

document.addEventListener('click',event=>{const b=event.target.closest('[data-cosmetic-preview]');if(!b)return;event.preventDefault();event.stopImmediatePropagation();const[kind,id]=b.dataset.cosmeticPreview.split(':'),look={...equippedCosmetic(),[kind==='costume'?'outfit':'accessory']:id};openOperator(profile.hero,undefined,look)},true);
